    getWidths: function(sizeInfo) {

        var itemsResult = {},
            colSize;

        if (sizeInfo && sizeInfo.col) {
            if (sizeInfo.col instanceof Array)
                colSize = sizeInfo.col;
            else
                colSize = [sizeInfo.col];
        } else if (sizeInfo) {
            colSize = sizeInfo;
        } else
            return [];

        colSize.forEach(function(element) {

            element["@columnId"] = element["@columnId"].replace(/&lt;measures&gt;/g, "<measures>");

            if (element["@label"] == '<measures>' || element['@label'] == '&lt;measures&gt;')
                element["@label"] = 'Measures';


            if (element.minWidth !== '' && element.minWidth !== undefined && element.width !== '' && element.width !== undefined) {
                itemsResult[element["@columnId"]] = {
                    "minWidth": parseInt(element.minWidth),
                    "width": parseInt(element.width)
                };
            } else if ((element.minWidth === '' || element.minWidth === undefined) && element.width !== '' && element.width !== undefined) {
                itemsResult[element["@columnId"]] = {
                    "minWidth": 0,
                    "width": parseInt(element.width)
                };
            } else if (element.minWidth !== '' && element.minWidth !== undefined && (element.width === '' || element.width === undefined)) {
                itemsResult[element["@columnId"]] = {
                    "minWidth": parseInt(element.minWidth),
                    "width": 'auto'
                };
            }
        });

        return itemsResult;

    },

