    getImageRange: function(obj) {



        var style = 'font-size:15px;text-align:center;color: ' + obj.color + ' ;background: transparent!important;',
            toReturn = {
                background: undefined,
                value: undefined,
                hasText: false
            };

        switch (obj.symbol) {
            case 'none':
                toReturn.value = "<div style=\"" + obj.font + "color:" + obj.color + ";\">" + obj.valueNumber + "</div>";
                toReturn.hasText = true;
                break;
            case 'horizArrow':
                toReturn.value = '<div class="ids-vaadin-icon-right-bold" style="' + style + '"></div>';
                break;
            case 'circle':
                toReturn.value = '<div class="ids-vaadin-icon-circle" style="' + style + '"></div>';
                break;
            case 'upArrow':
                toReturn.value = '<div class="ids-vaadin-icon-up-bold" style="' + style + '"></div>';
                break;
            case 'downArrow':
                toReturn.value = '<div class="ids-vaadin-icon-down-bold" style="' + style + '"></div>';
                break;
        }
        toReturn.background = obj.background;

        return toReturn;



    },

    rendererDimension: function(value, metaData, record, rowIndex, colIndex, store, view) {



        var me = this,
            tipVal,
            viewConfig = store.viewConfig,
            fontDimension = viewConfig.fontDimension,
            style = "",
            CSSUtils = viewConfig.CSSUtils,
            columns = view.headerCt.grid.columns,
            isLink = value.isLink,
            url = value.linkValue,
            linkNewTab = value.linkNewTab;

        style += fontDimension;

        if (colIndex > 0) {
            if (columns[colIndex - 1].hidden) {
                style += CSSUtils.esVer;
            }
        } else {
            style += CSSUtils.esVer;
        }

        tipVal = value.value;

        if (value.img) {
            tipVal = value.value.valueNumber;

            value.value.font = fontDimension;

            value = me.getImageRange(value.value);
            style += " background: " + value.background + ";";
        } else {

            if (value.bgColor) {
                style += "background:" + value.bgColor + ";";
            } else if (value.calculado) {
                style += me.calculadoColorDark;
                metaData.tdCls += 'cellGridStyle';
            } else {
                style += rowIndex % 2 === 0 ? me.alternatingColor1 : me.alternatingColor2;
                metaData.tdCls += 'cellGridStyle';
            }
            metaData.tdCls += ' showTooltip ';
        }

        metaData.tdStyle = style;
        metaData.style += me.verticalSeparator + me.horizontalSeparator;
        metaData.tdCls += " theme_default_font ";

        if (isLink) {
            return me.createLink(url, value.value, linkNewTab);
        }

        return value.value;

    },

